68:     * @param audioManager audio manager
69:     * @param address Address for device to set gain
70:     * @param gainInMillibels gain in millibels to set
71:     * @param isOutput is the device an output device
72:     * @return true if the gain was successfully set
73:     */
74:    public static boolean setAudioDeviceGain(@NonNull AudioManager audioManager,
75:            @NonNull String address, int gainInMillibels, boolean isOutput) {
76:        Preconditions.checkNotNull(audioManager,
77:                "Audio Manager can not be null in set device gain, device address %s", address);
78:        AudioDeviceInfo deviceInfo = getAudioDeviceInfo(audioManager, address, isOutput);
79:
80:        AudioGain audioGain = getAudioGain(deviceInfo.getPort());
81:
82:        // size of gain values is 1 in MODE_JOINT
83:        AudioGainConfig audioGainConfig = audioGain.buildConfig(
84:                AudioGain.MODE_JOINT,
85:                audioGain.channelMask(),
86:                new int[] { gainInMillibels },
87:                0);
88:        if (audioGainConfig == null) {
89:            throw new IllegalStateException("Failed to construct AudioGainConfig for device "
90:                    + address);
91:        }
92:
93:        int r = AudioManager.setAudioPortGain(deviceInfo.getPort(), audioGainConfig);
94:        if (r == AudioManager.SUCCESS) {
95:            return true;
96:        }
97:        return false;
98:    }
99:
100:    private static AudioDeviceInfo getAudioDeviceInfo(@NonNull AudioManager audioManager,
101:            @NonNull String address, boolean isOutput) {
102:        Objects.requireNonNull(address, "Device address can not be null");
103:        Preconditions.checkStringNotEmpty(address, "Device Address can not be empty");
104:
105:        AudioDeviceInfo[] devices =
106:                audioManager.getDevices(isOutput ? GET_DEVICES_OUTPUTS : GET_DEVICES_INPUTS);
107:
108:        for (int index = 0; index < devices.length; index++) {
109:            AudioDeviceInfo device = devices[index];
110:            if (address.equals(device.getAddress())) {
111:                return device;
112:            }
113:        }
114:
115:        throw new IllegalStateException((isOutput ? "Output" : "Input")
116:                + " Audio device info not found for device address " + address);
117:    }
118:
119:    private static AudioGain getAudioGain(@NonNull AudioDevicePort deviceport) {
120:        Objects.requireNonNull(deviceport, "Audio device port can not be null");
121:        Preconditions.checkArgument(deviceport.gains().length > 0,
122:                "Audio device must have gains defined");
123:        for (int index = 0; index < deviceport.gains().length; index++) {
124:            AudioGain gain = deviceport.gains()[index];
125:            if ((gain.mode() & AudioGain.MODE_JOINT) != 0) {
126:                return checkAudioGainConfiguration(gain);
127:            }
128:        }
129:        throw new IllegalStateException("Audio device does not have a valid audio gain");
130:    }
131:
132:    private static AudioGain checkAudioGainConfiguration(@NonNull AudioGain audioGain) {
133:        Preconditions.checkArgument(audioGain.maxValue() >= audioGain.minValue(),
134:                "Max gain %d is lower than min gain %d",
135:                audioGain.maxValue(), audioGain.minValue());
136:        Preconditions.checkArgument((audioGain.defaultValue() >= audioGain.minValue())
137:                && (audioGain.defaultValue() <= audioGain.maxValue()),
138:                "Default gain %d not in range (%d,%d)", audioGain.defaultValue(),
139:                audioGain.minValue(), audioGain.maxValue());
140:        Preconditions.checkArgument(
141:                ((audioGain.maxValue() - audioGain.minValue()) % audioGain.stepValue()) == 0,
142:                "Gain step value %d greater than min gain to max gain range %d",
143:                audioGain.stepValue(), audioGain.maxValue() - audioGain.minValue());
144:        Preconditions.checkArgument(
145:                ((audioGain.defaultValue() - audioGain.minValue()) % audioGain.stepValue()) == 0,
146:                "Gain step value %d greater than min gain to default gain range %d",
147:                audioGain.stepValue(), audioGain.defaultValue() - audioGain.minValue());
148:        return audioGain;
149:    }
