825:            List<AudioDeviceAttributes> devices, int flag) {
826:        int addressesSize = devices.size();
827:        Set<String> deviceAddressMap = new HashSet<>(addressesSize);
828:        for (int i = 0; i < addressesSize; ++i) {
829:            AudioDeviceAttributes device = devices.get(i);
830:            deviceAddressMap.add(device.getAddress());
831:        }
832:        List<AudioDeviceInfo> deviceInfoList = new ArrayList<>(devices.size());
833:        AudioDeviceInfo[] inputDevices = mAudioManager.getDevices(flag);
834:        for (int i = 0; i < inputDevices.length; ++i) {
835:            AudioDeviceInfo info = inputDevices[i];
836:            if (info.isSource() && deviceAddressMap.contains(info.getAddress())) {
837:                deviceInfoList.add(info);
838:            }
839:        }
