86:                generateBusToCarAudioDeviceInfo(carAudioDeviceInfos);
87:
88:        mLegacyAudioContextToBus =
89:                loadBusesForLegacyContexts(audioControlWrapper);
90:        mInputDevices = inputDevices;
91:    }
92:
93:    /* Loads mapping from {@link CarAudioContext} values to bus numbers
94:     * <p>Queries {@code IAudioControl#getBusForContext} for all
95:     * {@code CArAudioZoneHelper.LEGACY_CONTEXTS}. Legacy
96:     * contexts are those defined as part of
97:     * {@code android.hardware.automotive.audiocontrol.V1_0.ContextNumber}
98:     *
99:     * @param audioControl wrapper for IAudioControl HAL interface.
100:     * @return SparseIntArray mapping from {@link CarAudioContext} to bus number.
101:     */
102:    private static SparseIntArray loadBusesForLegacyContexts(
103:            @NonNull AudioControlWrapperV1 audioControlWrapper) {
104:        SparseIntArray contextToBus = new SparseIntArray();
105:
106:        for (int legacyContext : LEGACY_CONTEXTS) {
107:            int bus = audioControlWrapper.getBusForContext(legacyContext);
108:            validateBusNumber(legacyContext, bus);
109:            contextToBus.put(legacyContext, bus);
110:        }
111:        return contextToBus;
112:    }
113:
114:    private static void validateBusNumber(int legacyContext, int bus) {
115:        if (bus == NO_BUS_FOR_CONTEXT) {
116:            throw new IllegalArgumentException(
117:                    String.format("Invalid bus %d was associated with context %s", bus,
118:                            CarAudioContext.toString(legacyContext)));
119:        }
120:    }
121:
122:    private static SparseArray<CarAudioDeviceInfo> generateBusToCarAudioDeviceInfo(
123:            List<CarAudioDeviceInfo> carAudioDeviceInfos) {
124:        SparseArray<CarAudioDeviceInfo> busToCarAudioDeviceInfo = new SparseArray<>();
125:
126:        for (CarAudioDeviceInfo carAudioDeviceInfo : carAudioDeviceInfos) {
127:            int busNumber = parseDeviceAddress(carAudioDeviceInfo.getAddress());
128:            if (busNumber >= 0) {
129:                if (busToCarAudioDeviceInfo.get(busNumber) != null) {
130:                    throw new IllegalArgumentException("Two addresses map to same bus number: "
131:                            + carAudioDeviceInfo.getAddress()
132:                            + " and "
133:                            + busToCarAudioDeviceInfo.get(busNumber).getAddress());
134:                }
135:                busToCarAudioDeviceInfo.put(busNumber, carAudioDeviceInfo);
136:            }
137:        }
138:
139:        return busToCarAudioDeviceInfo;
140:    }
141:
142:    SparseArray<CarAudioZone> loadAudioZones() {
143:        CarAudioZone zone = new CarAudioZone(PRIMARY_AUDIO_ZONE, "Primary zone");
144:        for (CarVolumeGroup volumeGroup : loadVolumeGroups()) {
145:            zone.addVolumeGroup(volumeGroup);
146:        }
147:        SparseArray<CarAudioZone> carAudioZones = new SparseArray<>();
148:        addMicrophonesToPrimaryZone(zone);
149:        carAudioZones.put(PRIMARY_AUDIO_ZONE, zone);
150:
151:        return carAudioZones;
152:    }
153:
154:    /**
155:     * @return all {@link CarVolumeGroup} read from configuration.
156:     */
157:    private List<CarVolumeGroup> loadVolumeGroups() {
158:        List<CarVolumeGroup> carVolumeGroups = new ArrayList<>();
159:        try (XmlResourceParser parser = mContext.getResources().getXml(mXmlConfiguration)) {
160:            AttributeSet attrs = Xml.asAttributeSet(parser);
161:            int type;
162:            // Traverse to the first start tag
163:            while ((type = parser.next()) != XmlResourceParser.END_DOCUMENT
164:                    && type != XmlResourceParser.START_TAG) {
165:                // ignored
166:            }
167:
168:            if (!TAG_VOLUME_GROUPS.equals(parser.getName())) {
169:                throw new IllegalArgumentException(
170:                        "Meta-data does not start with volumeGroups tag");
171:            }
172:            int outerDepth = parser.getDepth();
173:            int id = 0;
174:            while ((type = parser.next()) != XmlResourceParser.END_DOCUMENT
175:                    && (type != XmlResourceParser.END_TAG || parser.getDepth() > outerDepth)) {
176:                if (type == XmlResourceParser.END_TAG) {
177:                    continue;
178:                }
179:                if (TAG_GROUP.equals(parser.getName())) {
180:                    carVolumeGroups.add(parseVolumeGroup(id, attrs, parser));
181:                    id++;
182:                }
183:            }
184:        } catch (Exception e) {
185:            Slogf.e(CarLog.TAG_AUDIO, "Error parsing volume groups configuration", e);
186:        }
187:        return carVolumeGroups;
188:    }
189:
190:    private CarVolumeGroup parseVolumeGroup(int id, AttributeSet attrs,
191:            XmlResourceParser parser) throws XmlPullParserException, IOException {
192:        CarVolumeGroup.Builder builder = new CarVolumeGroup.Builder(PRIMARY_AUDIO_ZONE, id,
193:                mCarAudioSettings, /* useCarVolumeGroupMute= */ false);
194:
195:        List<Integer> audioContexts = parseAudioContexts(parser, attrs);
196:
197:        for (int i = 0; i < audioContexts.size(); i++) {
198:            bindContextToBuilder(builder, audioContexts.get(i));
199:        }
200:
201:        return builder.build();
202:    }
203:
204:
205:    private void bindContextToBuilder(CarVolumeGroup.Builder groupBuilder, int legacyAudioContext) {
206:        int busNumber = mLegacyAudioContextToBus.get(legacyAudioContext);
207:        CarAudioDeviceInfo info = mBusToCarAudioDeviceInfo.get(busNumber);
208:        groupBuilder.setDeviceInfoForContext(legacyAudioContext, info);
209:
210:        if (legacyAudioContext == CarAudioService.DEFAULT_AUDIO_CONTEXT) {
211:            CarAudioZonesHelper.setNonLegacyContexts(groupBuilder, info);
212:        }
213:    }
214:
215:    private List<Integer> parseAudioContexts(XmlResourceParser parser, AttributeSet attrs)
216:            throws IOException, XmlPullParserException {
217:        List<Integer> contexts = new ArrayList<>();
218:        int type;
219:        int innerDepth = parser.getDepth();
220:        while ((type = parser.next()) != XmlResourceParser.END_DOCUMENT
221:                && (type != XmlResourceParser.END_TAG || parser.getDepth() > innerDepth)) {
222:            if (type == XmlResourceParser.END_TAG) {
223:                continue;
224:            }
225:            if (TAG_CONTEXT.equals(parser.getName())) {
226:                TypedArray c = mContext.getResources().obtainAttributes(
227:                        attrs, R.styleable.volumeGroups_context);
228:                contexts.add(c.getInt(R.styleable.volumeGroups_context_context, -1));
229:                c.recycle();
230:            }
231:        }
232:
233:        return contexts;
234:    }
235:
236:    private void addMicrophonesToPrimaryZone(CarAudioZone primaryAudioZone) {
237:        for (int index = 0; index < mInputDevices.length; index++) {
238:            AudioDeviceInfo info = mInputDevices[index];
239:            if (isMicrophoneInputDevice(info)) {
240:                primaryAudioZone.addInputAudioDevice(new AudioDeviceAttributes(info));
241:            }
242:        }
243:    }
244:
245:    /**
246:     * Parse device address. Expected format is BUS%d_%s, address, usage hint
247:     *
248:     * @return valid address (from 0 to positive) or -1 for invalid address.
249:     */
250:    private static int parseDeviceAddress(String address) {
251:        String[] words = address.split("_");
252:        int addressParsed = -1;
253:        if (words[0].toLowerCase().startsWith("bus")) {
254:            try {
255:                addressParsed = Integer.parseInt(words[0].substring(3));
256:            } catch (NumberFormatException e) {
257:                //ignore
258:            }
259:        }
260:        if (addressParsed < 0) {
261:            return -1;
262:        }
263:        return addressParsed;
264:    }
